function MeanAbsoluteDeviation(numbers : array of real): real; 
begin
  var
    n := Length(numbers);
    var
      x_mean := Average(numbers);
      MAD := 0.0;
  for var i := 0 to n - 1 do
    MAD += Abs(numbers[i] - x_mean);
  MAD := MAD / n;
  Result := MAD;
end;


function Intersperse(numbers : array of integer; delimeter : integer): array of integer; 
begin
  if (length(numbers) = 0) then
    exit([]);

  var
    result := [];
    i := 0;

  while (i < length(numbers)) do
  begin
    insert(delimeter, numbers[i], i);
    i += 1;
  end;

  result := remove(delimeter, 0, length(numbers));
  exit(result);
end;


