function MakePalindrome(str : string): string;
var
  i, j: integer;
  s: string;
begin
  Result := '';
  s := str;
  for i := 1 to length(s) do
  begin
    if IsPalindrome(CopyString(s, 1, i)) then
    begin
      Result := s + ReverseString(CopyString(s, i, length(s) - i));
      break;
    end;
  end;
end;


function StringXor(a : string; b : string): string;
begin
  Result := '';
  for i := 0 to Max(Length(a), Length(b)) - 1 do
  begin
    if (i >= Length(a)) or (i >= Length(b)) then
      Result := Result + '0'
    else
      Result := Result + (a[i+1] xor b[i+1]);
  end;
end;


