function ParseMusic(musicString : string): array of integer; 
begin
  var
    result := new integer[10];
    var
      i := 0;
    while i < musicString.Length do
    begin
      if musicString[i] = 'o' then
        result[i mod 10] += 4
      else if musicString[i] = 'o' and musicString[i + 1] = '|' then
        result[i mod 10] += 2
      else if musicString[i] = '.' and musicString[i + 1] = '|' then
        result[i mod 10] += 1
      i += 1;
    end;
    Result := result;
end;


function HowManyTimes(str : string; substring : string): integer;  { Find how many times a given substring can be found in the original string. Count overlaping cases.
begin
  var
    count : integer := 0;
    i : integer := 0;
  begin
    while i <= (length(str) - length(substring)) do
    begin
      if str[i] = substring[1] then
      begin
        if substring = str[i..i+length(substring)-1]] then
          count := count + 1;
      end;
      i := i + 1;
    end;
    Result := count;
  end;
end;


