function RescaleToUnit(numbers : array of real): array of real; 
begin
  var
    min, max, i: real;
  begin
    if (Length(numbers) < 2) then
      raise new System.ArgumentException('Array of at least two elements is expected.');

    min := numbers[0];
    max := numbers[0];

    for i := 1 to Length(numbers) - 1 do
    begin
      if (numbers[i] < min) then
        min := numbers[i];

      if (numbers[i] > max) then
        max := numbers[i];
    end;

    for i := 0 to Length(numbers) - 1 do
      numbers[i] := (numbers[i] - min) / (max - min);

    Result := numbers;
  end;
end.


