function SortThird(l : array of integer): array of integer; 
begin
  var
    i, j, k: integer;
    thirds: array of integer;
    count: integer;
  begin
    count := 0;
    for i := 0 to l.Length - 1 do
    begin
      if i mod 3 = 0 then
      begin
        thirds[count] := l[i];
        Inc(count);
      end;
    end;

    for i := 0 to thirds.Length - 1 do
    begin
      for j := i + 1 to thirds.Length - 1 do
      begin
        if thirds[i] > thirds[j] then
        begin
          Swap(thirds[i], thirds[j]);
        end;
      end;
    end;

    count := 0;
    for i := 0 to l.Length - 1 do
    begin
      if i mod 3 = 0 then
      begin
        l[i] := thirds[count];
        Inc(count);
      end;
    end;

    Result := l;
  end;


