function PrimeFib(n : integer) : integer;
{ prime_fib returns n-th number that is a Fibonacci number and it's also prime. }
begin
  Result := 0;
  if n <= 0 then
    exit;
  if n = 1 then
    Result := 2;
  if n = 2 then
    Result := 5;
  if n mod 2 = 0 then
    Result := 2 * PrimeFib(n div 2)
  else
    Result := 2 * PrimeFib((n + 1) div 2) + 1;
end;


function TriplesSumToZero(l : array of integer): boolean;  {
    var
        n: integer;
        found: boolean;
    begin
        n := sizeof(l) - 1;
        found := False;
        while (n > 1) do
        begin
            l.Sort;
            var
                i, j, k: integer;
            begin
                i := 0;
                j := n - 1;
                while (i < j) do
                begin
                    if (l[i] + l[j] + l[k] = 0) then
                    begin
                        found := True;
                        break;
                    end;

                    if (l[i] + l[j] + l[k] < 0) then
                        i := i + 1
                    else
                        j := j - 1;
                end;

                if (found) then
                    break;

                n := n - 1;
            end;
        end;

        Result := found;
    end;

