function Fib4(n : integer): integer; 
begin
  if n < 2 then
    Fib4 := 0
  else if n = 2 then
    Fib4 := 2
  else if n = 3 then
    Fib4 := 0
  else
    Fib4 := Fib4(n-1) + Fib4(n-2) + Fib4(n-3) + Fib4(n-4);
end;


function Median(l : array of integer): real; 
begin
  var
    n := l.Length;
    s := new real[n];
    var i := 0;
    for var x in l do
    begin
      s[i] := x;
      i += 1;
    end;
    Sort(s);
    if n mod 2 = 0 then
      Result := (s[n div 2 - 1] + s[n div 2]) / 2
    else
      Result := s[n div 2];
end;


function IsPalindrome(text : string): boolean;  {
    Checks if a string is a palindrome

    var
        left, right: integer;
    begin
        left := 1;
        right := length(text);

        while (left < right) do
        begin
            if (text[left] <> text[right]) then
                exit(False);

            left := left + 1;
            right := right - 1;
        end;

        Result := True;
    end;
end;


