function LargestPrimeFactor(n : integer): integer;
{
  var
    i, j, max: integer;
  begin
    Result := 2;
    if n mod 2 = 0 then
      n := n div 2
    else
      n := n - 1;
    for i := 2 to Round(Sqrt(n)) do
    begin
      if n mod i = 0 then
      begin
        n := n div i;
        j := i;
        while n mod j = 0 do
        begin
          j := j div i;
        end;
        if j > max then
        begin
          Result := i;
          max := j;
        end;
      end;
    end;
    if n > 1 then
      Result := n;
  end;
end;


