function Fibfib(n : integer): integer; 
begin
  if n < 0 then
    raise new System.ArgumentOutOfRangeException('n', n, 'n must be greater or equals 0')
  else
  begin
    if n = 0 then
      Result := 0
    else if n = 1 then
      Result := 0
    else if n = 2 then
      Result := 1
    else
      Result := Fibfib(n-1) + Fibfib(n-2) + Fibfib(n-3);
  end;
end;


