  a := aArr.sum(x -> x.tointeger);
  o := oArr.sum(x -> x.tointeger);
  Result := n - a - o;
end;


function Pluck(arr : array of integer): array of integer; 
begin
  var
    smallest_value := MaxValue;
    smallest_index := MaxValue;
    found := False;

  for var i := 0 to Length(arr) - 1 do
  begin
    if arr[i] < smallest_value then
    begin
      smallest_value := arr[i];
      smallest_index := i;
      found := True;
    end
    else if arr[i] = smallest_value then
    begin
      if i < smallest_index then
        smallest_index := i;
      found := True;
    end;
  end;

  if not found then
    Result := []
  else
    Result := [smallest_value, smallest_index];
end;


