function StrangeSortList(lst : array of integer): array of integer;  {
    var
        n: integer;
        i: integer;
        min, max: integer;
        newArr: array of integer;
    begin
        n := length(lst);
        if n = 0 then
            exit(lst);
        newArr := lst;
        repeat
            min := newArr[0];
            for i := 1 to n - 1 do
                if newArr[i] < min then
                    min := newArr[i];
            for i := 0 to n - 1 do
                if newArr[i] = min then
                begin
                    newArr[i] := 0;
                    break;
                end;
            max := newArr[0];
            for i := 1 to n - 1 do
                if newArr[i] > max then
                    max := newArr[i];
            for i := 0 to n - 1 do
                if newArr[i] = max then
                begin
                    newArr[i] := 0;
                    break;
                end;
        until newArr[0] = 0;
        Result := newArr;
    end;

