end;


function WillItFly(q : array of integer; w : integer): boolean; 
begin
  Result := True;
  if not (All(q, function(x: integer): boolean 
    begin
      Result := Result and (x in q);
    end)) then
    Exit;
  if not (All(q, function(x: integer): boolean 
    begin
      Result := Result and (x <= w);
    end)) then
    Exit;
  if not (All(q, function(x: integer): boolean 
    begin
      Result := Result and (x <= Sum(q) - w);
    end)) then
    Exit;
end;


function smallestChange(arr: array of integer): integer;
begin
  var
    left, right: integer;
    count: integer;
  begin
    left := 0;
    right := length(arr) - 1;
    count := 0;
    while left < right do
    begin
      if arr[left] <> arr[right] then
        Inc(count);
      Inc(left);
      Dec(right);
    end;
    Result := count;
  end;


