function IsMultiplyPrime(a : integer): boolean;
begin
  var prime1, prime2, prime3 : integer;
  var i := 2;
  while i*i <= a do
  begin
    if a mod i = 0 then
    begin
      prime1 := i;
      a := a div i;
    end
    else
      i += 1;
  end;

  if a > 1 then
  begin
    prime2 := a;
  end;

  i := 2;
  while i*i*i <= a do
  begin
    if a mod i = 0 then
    begin
      prime3 := i;
      a := a div i;
    end
    else
      i += 1;
  end;

  if a > 1 then
  begin
    prime3 := a;
  end;

  if prime1 = 3 and prime2 = 5 and prime3 = 7 then
    Result := True
  else
    Result := False;
end;


