  a := abs(a);
  b := abs(b);
  product := 0;
  while a > 0 do
  begin
    aDigit := a mod 10;
    bDigit := b mod 10;
    a := a div 10;
    b := b div 10;
    product := product + (aDigit * bDigit);
  end;
  Result := product;
end;


