    s2 := lst[1];
    match := true;
    i := 1;
    j := 1;
    while match and (i < s1.Length) and (j < s2.Length) do
    begin
      if s1[i] = '(' then
        Inc(i)
      else
        Inc(j);
      if s1[i] = ')' then
        Dec(i);
      if s2[j] = '(' then
        Inc(j)
      else
        Dec(i);
      match := match and (s1[i] = s2[j]);
    end;
