function Minpath(grid : array of array of integer; k : integer): array of integer;
begin
  var N := length(grid);
  var res := new integer[k];
  var visited := new boolean[N, N];
  for var i := 0 to N - 1 do
    for var j := 0 to N - 1 do
      visited[i, j] := false;
  var dfs := procedure (i, j, step : integer) :=
    begin
      if step = k then
      begin
        res[step - 1] := grid[i, j];
        exit;
      end;
      visited[i, j] := true;
      if i - 1 >= 0 then dfs(i - 1, j, step + 1);
      if j - 1 >= 0 then dfs(i, j - 1, step + 1);
      if i + 1 < N then dfs(i + 1, j, step + 1);
      if j + 1 < N then dfs(i, j + 1, step + 1);
      visited[i, j] := false;
    end;
  dfs(N - 1, N - 1, 1);
  var output := new integer[k];
  for var i := 0 to k - 1 do
    output[i] := res[i];
  result := output;
end;


