function SumSquares(lst : array of integer): integer;
begin
  var
    sum := 0;
    for i := 0 to lst.Length - 1 do
    begin
      if i mod 3 = 0 then
        sum := sum + lst[i] * lst[i] * lst[i]
      else if i mod 4 = 0 then
        sum := sum + lst[i] * lst[i] * lst[i] * lst[i]
      else
        sum := sum + lst[i];
    end;
    Result := sum;
end;


function WordsInPrimeLength(sentence: string): string;
begin
  var
    words: array of string;
    primeWords: array of string;
    word: string;
    prime: boolean;
    i: integer;
  begin
    words := Split(sentence, ' ');
    for i := 0 to Length(words) - 1 do
    begin
      word := words[i];
      prime := True;
      if Length(word) > 1 then
        prime := False;
      for j := 2 to Sqrt(Length(word)) do
        if Length(word) mod j = 0 then
          prime := False;
      if prime then
        Append(primeWords, word);
    end;
    Result := Join(primeWords, ' ');
  end;


