function OrderByPoints(nums : array of integer): array of integer;
begin
  var
    n: integer;
    sum: integer;
    i: integer;
    j: integer;
    temp: integer;
    flag: boolean;
    sortedNums: array of integer;
  begin
    n := length(nums);
    if n = 0 then
      exit(sortedNums);

    for i := 0 to n-1 do
    begin
      sum := 0;
      flag := false;
      for j := i to n-1 do
      begin
        if (nums[j] >= 0) and (nums[j] < 10) then
          sum := sum + nums[j]
        else
          flag := true;
      end;

      if flag then
        continue;

      for j := i+1 to n-1 do
      begin
        if (sum <> 0) and (sum <> sum + nums[j]) then
          continue;

        if (sum = sum + nums[j]) and (i < j) then
        begin
          temp := nums[i];
          nums[i] := nums[j];
          nums[j] := temp;
        end;
      end;
    end;

    for i := 0 to n-1 do
      sortedNums[i] := nums[i];

    exit(sortedNums);
  end;


function Specialfilter(nums : array of integer): integer;
begin
  Result := 0;
  for var i := 0 to Length(nums) - 1 do
  begin
    var n := Abs(nums[i]);
    var last := n mod 10;
    var first := n;
    while first >= 10 do
      first := first div 10;
    while first >= 10 do
      first := first div 10;
    if n < 0 then
      first := -first
    else if n mod 2 = 1 then
      first := -first
    if last = 1 then
      if n < 0 then
        last := -last
      else if n mod 2 = 1 then
        last := -last
    if n < 0 then
      last := -last
    else if n mod 2 = 1 then
      last := -last
    if n < 0 then
      n := -n
    if n > 10 and n = last then
      Result := Result + 1;
  end;
end;


