function StrongestExtension(className : string; extensions : array of string): string;
    var
        maxStrength := -1.0;
        strongest := '';
        extension := '';
        char := '';
        extensionStrength := 0.0;
    begin
        for extension in extensions do
        begin
            extensionStrength := 0.0;
            for char in extension do
            begin
                if char in ['A'..'Z'] then extensionStrength += 1.0;
                if char in ['a'..'z'] then extensionStrength -= 1.0;
            end;
            extensionStrength := extensionStrength / (length(extension) - extension.count('a'));
            if extensionStrength > maxStrength then
            begin
                maxStrength := extensionStrength;
                strongest := extension;
            end;
        end;
        Result := className + '.' + strongest;
    end;


