function Eat(number, need, remaining : integer): (integer, integer);
begin
  if (number >= need) and (remaining >= need) then
    Result := (number + need, remaining - need)
  else if (remaining >= need) then
    Result := (number, remaining - need)
  else
    Result := (number, 0);
end;


function operator_function(operator: string; a, b: integer): integer;
begin
  case operator of
    '+': Result := a + b;
    '-': Result := a - b;
    '*': Result := a * b;
    '//': Result := a div b;
    '**': Result := a ** b;
  end;
end;

function do_algebra(operator: array of string; operand: array of integer): integer;
begin
  Result := operator_function(operator[0], operand[0], operand[1]);
  for var i := 1 to operator.Length - 1 do
  begin
    Result := operator_function(operator[i], Result, operand[i + 1]);
  end;
end;


function Solve(s : string): string;
begin
  if s = '' then
