  else
    Result := '';
  for var i := 1 to Length(s) do
  begin
    if s[i] in ['a'..'z'] then
      Result := Result + UpperCase(s[i])
    else if s[i] in ['A'..'Z'] then
      Result := Result + LowerCase(s[i])
    else
      Result := Result + s[i]
  end;
end;


